test.describe("navigation", () => {
  test("Navigation: \"Next →\" leads to /page/2/", async ({ page, request }) => {
    await page.goto(at("/"));
    await page.locator('a[href=' + "\"/page/2/\"" + ']').first().click();
    const trim = (p) => (p.length > 1 ? p.replace(/\/$/, '') : p);
    await page.waitForURL((url) => trim(url.pathname + url.search) === "/page/2");
  });
});

