test.describe("forms", () => {
  test("Form /login on /login: valid data passes validation (not submitted)", async ({ page, request }) => {
    await page.goto(at("/login"));
    const form = page.locator('form').nth(0);
    await form.locator("#username").first().fill("Test value");
    await form.locator("#password").first().fill("Passw0rd!xyz");
    expect(await form.evaluate((f) => [...f.elements].filter((el) => el.willValidate && !el.validity.valid).map((el) => el.name || el.id))).toEqual([]);
  });
});
